"""Run-local stdio MCP bridge; only execute is exposed, never controller grading."""
import asyncio
import json
from pathlib import Path
import sys

# Actionable guidance appended whenever the AppWorld sandbox rejects an import of
# the pre-injected API client. Keep this general: it is about the execution
# contract, not about any one task.
_BLOCKED_IMPORT_HINT = (
    "The AppWorld API client `apis` is already pre-injected and available as a "
    "global object in the sandbox. Remove any `import apis...` statement and call "
    "`apis.<service>.<api>()` directly (for example, "
    "print(apis.api_docs.show_app_descriptions()))."
)

TOOL_DESCRIPTION = (
    "Execute Python code in the supplied persistent AppWorld shell and return its "
    "printed output. The AppWorld API client `apis` is already available as a "
    "pre-injected global object in that shell; call it directly, e.g. "
    "print(apis.api_docs.show_app_descriptions()). Do NOT use `import apis` or "
    "`import apis.api_docs`; those imports are blocked by the sandbox and will fail."
)


def make_execute_result(raw):
    """Forward AppWorld's response, adding actionable guidance for blocked imports.

    AppWorld returns a JSON object such as
    {"output": "Execution failed. Traceback:\\nUsage of the following module is not
    allowed: apis.", "task_completed": false}. When the output indicates a blocked
    module import, append the direct-call hint so the agent can self-correct instead
    of retrying the same import.
    """
    try:
        payload = json.loads(raw)
    except (json.JSONDecodeError, TypeError):
        return raw
    if not isinstance(payload, dict):
        return raw
    output = payload.get("output", "")
    if isinstance(output, str) and "not allowed" in output:
        payload["output"] = output.rstrip() + "\n" + _BLOCKED_IMPORT_HINT
        return json.dumps(payload)
    return raw


async def execute(code):
    socket = json.loads(Path('appworld-connection.json').read_text())['socket']
    reader, writer = await asyncio.open_unix_connection(socket, limit=8 * 1024 * 1024)
    try:
        writer.write((json.dumps({'operation': 'execute', 'code': code}) + '\n').encode())
        await writer.drain()
        return (await reader.readline()).decode().strip()
    finally:
        writer.close()
        await writer.wait_closed()


def main():
    for line in sys.stdin:
        request = json.loads(line)
        if 'id' not in request:
            continue
        method = request['method']
        try:
            if method == 'initialize':
                result = {'protocolVersion': request['params']['protocolVersion'],
                          'capabilities': {'tools': {}},
                          'serverInfo': {'name': 'appworld', 'version': '1.0.0'}}
            elif method == 'ping':
                result = {}
            elif method == 'tools/list':
                result = {'tools': [{'name': 'appworld_execute',
                          'description': TOOL_DESCRIPTION,
                          'inputSchema': {'type': 'object', 'properties': {'code': {'type': 'string'}}, 'required': ['code'], 'additionalProperties': False}}]}
            elif method == 'tools/call':
                if request['params']['name'] != 'appworld_execute':
                    raise ValueError('Unknown tool')
                output = asyncio.run(execute(request['params']['arguments']['code']))
                result = {'content': [{'type': 'text', 'text': make_execute_result(output)}]}
            else:
                print(json.dumps({'jsonrpc': '2.0', 'id': request['id'], 'error': {'code': -32601, 'message': 'Method not found'}}), flush=True)
                continue
        except Exception as error:
            result = {'content': [{'type': 'text', 'text': str(error)}], 'isError': True}
        print(json.dumps({'jsonrpc': '2.0', 'id': request['id'], 'result': result}), flush=True)


if __name__ == '__main__':
    main()

