"""Stop hook that keeps an AppWorld run from ending before the documented
supervisor completion API has actually been invoked.

This hook is fail-open only when it cannot obtain any usable evidence: if the
input cannot be parsed, or neither a transcript path nor a
``last_assistant_message`` is available, it approves the stop so a healthy run
can never be broken by the hook itself.

When evidence is available and no ``supervisor.complete_task(...)`` call is
found, the hook blocks the stop and returns a concrete reason for the model to
keep working. It intentionally does **not** gate the block on the CLI's
``stop_hook_active`` flag: the Claude Code SDK does not currently propagate that
flag to plugin Stop hooks, so it can be ``false`` even for an ordinary,
blockable turn end. The CLI's own block cap and turn limit still bound retries.
"""

import json
import re
import sys
from pathlib import Path

# Match an actual invocation such as ``apis.supervisor.complete_task(...)`` or
# ``supervisor.complete_task(...)``, but not documentation lookups like
# ``show_api_doc(app_name="supervisor", api_name="complete_task")``.
_COMPLETION_CALL = re.compile(r"(?:apis\.)?supervisor\.complete_task\s*\(")


def _extract_code(value):
    """Return the Python code string from a tool-use record, if one exists."""
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        code = value.get("code")
        if isinstance(code, str):
            return code
        for key in ("input", "arguments", "tool_input"):
            child = value.get(key)
            if isinstance(child, str):
                return child
            if isinstance(child, dict):
                code = _extract_code(child)
                if code:
                    return code
    return None


def _walk(value, found):
    if isinstance(value, dict):
        record_type = value.get("type")
        if record_type in {
            "ToolUseBlock",
            "tool_use",
            "tool_use_block",
            "toolUse",
            "ToolUse",
        }:
            code = _extract_code(value)
            if code and _COMPLETION_CALL.search(code):
                found.append(True)
        for child in value.values():
            _walk(child, found)
    elif isinstance(value, list):
        for child in value:
            _walk(child, found)


def _text_has_completion(text):
    if not isinstance(text, str) or not text.strip():
        return False
    return bool(_COMPLETION_CALL.search(text))


def _transcript_has_completion(transcript_path):
    """Return True/False, or None when the transcript is missing/unreadable."""
    path = Path(transcript_path)
    if not path.is_file():
        return None
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeError):
        return None

    # The transcript is normally JSONL; accept a single JSON array as well.
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        data = None

    found = []
    if isinstance(data, (dict, list)):
        _walk(data, found)
    else:
        for line in text.splitlines():
            if not line.strip():
                continue
            try:
                record = json.loads(line)
            except json.JSONDecodeError:
                continue
            _walk(record, found)
    return any(found)


def _approve():
    print(json.dumps({"decision": "approve"}), flush=True)


def _block():
    print(
        json.dumps(
            {
                "decision": "block",
                "reason": (
                    "Do not end the run yet: no apis.supervisor.complete_task(...) "
                    "call was found in the transcript. AppWorld grades final world "
                    "state, so a final text answer alone will fail. Perform the "
                    "required world-state changes, then call "
                    'print(apis.supervisor.complete_task(status="success")) and '
                    "wait for its result before ending your turn."
                ),
            }
        ),
        flush=True,
    )


def main():
    try:
        request = json.load(sys.stdin)
    except Exception:
        _approve()
        return

    if not isinstance(request, dict):
        _approve()
        return

    transcript_path = request.get("transcript_path") or request.get("transcript")
    last_message = request.get("last_assistant_message") or ""

    has_completion = None
    if transcript_path:
        has_completion = _transcript_has_completion(transcript_path)

    if has_completion is None and isinstance(last_message, str) and last_message.strip():
        has_completion = _text_has_completion(last_message)

    if has_completion:
        _approve()
        return

    if has_completion is None:
        # No usable evidence about the run; fail open rather than risk breaking
        # a healthy session that happens to use an unexpected input shape.
        _approve()
        return

    _block()


if __name__ == "__main__":
    main()

