"""Stop hook that keeps an AppWorld run from ending before the documented
supervisor completion API has actually been invoked.

This is deliberately fail-open: if the transcript is missing, unreadable, or in an
unexpected shape, the hook approves the stop so a healthy run can never be broken
by the hook itself. It also only blocks when the CLI says the hook is allowed to
block (`stop_hook_active`), matching Claude Code's Stop-hook contract.
"""

import json
import re
import sys
from pathlib import Path

# Match an actual invocation such as ``apis.supervisor.complete_task(...)`` or
# ``supervisor.complete_task(...)``, but not documentation lookups like
# ``show_api_doc(app_name="supervisor", api_name="complete_task")``.
_COMPLETION_CALL = re.compile(r"(?:apis\.)?supervisor\.complete_task\s*\(")


def _extract_code(value):
    """Return the Python code string from a tool-use record, if one exists."""
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        code = value.get("code")
        if isinstance(code, str):
            return code
        for key in ("input", "arguments", "tool_input"):
            child = value.get(key)
            if isinstance(child, str):
                return child
            if isinstance(child, dict):
                code = _extract_code(child)
                if code:
                    return code
    return None


def _walk(value, found):
    if isinstance(value, dict):
        record_type = value.get("type")
        if record_type in {"ToolUseBlock", "tool_use", "tool_use_block"}:
            code = _extract_code(value)
            if code and _COMPLETION_CALL.search(code):
                found.append(True)
        for child in value.values():
            _walk(child, found)
    elif isinstance(value, list):
        for child in value:
            _walk(child, found)


def _transcript_has_completion(transcript_path):
    path = Path(transcript_path)
    if not path.is_file():
        return True
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeError):
        return True

    # The transcript is normally JSONL; accept a single JSON array as well.
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        data = None

    found = []
    if isinstance(data, (dict, list)):
        _walk(data, found)
    else:
        for line in text.splitlines():
            if not line.strip():
                continue
            try:
                record = json.loads(line)
            except json.JSONDecodeError:
                continue
            _walk(record, found)
    return any(found)


def _approve():
    print(json.dumps({"decision": "approve"}), flush=True)


def main():
    try:
        request = json.load(sys.stdin)
    except Exception:
        _approve()
        return

    if not isinstance(request, dict) or not request.get("stop_hook_active"):
        _approve()
        return

    transcript_path = request.get("transcript_path") or request.get("transcript")
    if not transcript_path or _transcript_has_completion(transcript_path):
        _approve()
        return

    print(
        json.dumps(
            {
                "decision": "block",
                "reason": (
                    "Do not end the run yet: no supervisor completion call "
                    "(apis.supervisor.complete_task) was found in the transcript. "
                    "Final answer text does not change world state. Perform the "
                    "required world-state changes, then call the documented "
                    "supervisor completion API before finishing."
                ),
            }
        ),
        flush=True,
    )


if __name__ == "__main__":
    main()
